function imageRequestSettings(imageUrl, target) {
  if (
    typeof imageUrl !== "string" ||
    imageUrl.length > 2000 ||
    !/^https:\/\/[a-z0-9]+(?:[.-][a-z0-9]+)*\.[a-z]{2,}(?:\/[^\s#]*)?$/i.test(imageUrl)
  ) {
    throw new Error("Enter a public HTTPS image URL with no embedded account credentials.");
  }
  if (typeof target !== "string" || !target.trim() || [...target.trim()].length > 300) {
    throw new Error("Describe the objects to detect in 1 to 300 characters.");
  }
  return { url: imageUrl, target: target.trim() };
}

return { json: imageRequestSettings("", "rabbits") };

function checkExifOrientation(bytes, from, end) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (end - from < 8) throw new Error("Invalid image orientation metadata.");
  const little = view.getUint16(from) === 0x4949;
  if ((!little && view.getUint16(from) !== 0x4d4d) || view.getUint16(from + 2, little) !== 42) {
    throw new Error("Invalid image orientation metadata.");
  }
  const start = from + view.getUint32(from + 4, little);
  if (start < from + 8 || start + 2 > end) throw new Error("Invalid image orientation metadata.");
  const entries = view.getUint16(start, little);
  if (start + 2 + entries * 12 > end) throw new Error("Invalid image orientation metadata.");
  for (let index = 0; index < entries; index++) {
    const field = start + 2 + index * 12;
    if (view.getUint16(field, little) !== 0x0112) continue;
    if (
      view.getUint16(field + 2, little) !== 3 ||
      view.getUint32(field + 4, little) !== 1 ||
      view.getUint16(field + 8, little) !== 1
    ) {
      throw new Error("Use an image stored upright with standard orientation.");
    }
  }
}

function pngDimensions(bytes, view) {
  if (view.getUint32(0) !== 0x89504e47 || view.getUint32(4) !== 0x0d0a1a0a)
    throw new Error("Invalid PNG signature.");
  let dimensions,
    imageData = false;
  for (let offset = 8; offset + 12 <= bytes.length;) {
    const length = view.getUint32(offset);
    const start = offset + 8;
    const end = start + length + 4;
    if (end > bytes.length) break;
    const chunk = String.fromCharCode(...bytes.subarray(offset + 4, start));
    if (offset === 8) {
      if (chunk !== "IHDR" || length !== 13) break;
      dimensions = { width: view.getUint32(start), height: view.getUint32(start + 4) };
    }
    if (chunk === "acTL") throw new Error("Use a static PNG image.");
    if (chunk === "eXIf") checkExifOrientation(bytes, start, end - 4);
    if (chunk === "IDAT" && length > 0) imageData = true;
    if (chunk === "IEND" && length === 0 && imageData && dimensions && end === bytes.length)
      return dimensions;
    offset = end;
  }
  throw new Error("Incomplete PNG image.");
}

function jpegDimensions(bytes, view) {
  if (view.getUint16(0) !== 0xffd8 || view.getUint16(bytes.length - 2) !== 0xffd9) {
    throw new Error("Invalid JPEG start or end.");
  }
  let dimensions;
  for (let offset = 2; offset + 4 < bytes.length;) {
    if (bytes[offset++] !== 0xff) break;
    while (bytes[offset] === 0xff) offset++;
    const marker = bytes[offset++];
    if (offset + 2 > bytes.length) break;
    const length = view.getUint16(offset);
    const start = offset + 2;
    const end = offset + length;
    if (length < 2 || end >= bytes.length - 2) break;
    if ([0xc0, 0xc1, 0xc2].includes(marker)) {
      if (dimensions || length < 8) break;
      dimensions = { width: view.getUint16(start + 3), height: view.getUint16(start + 1) };
    }
    if (
      marker === 0xe1 &&
      length >= 8 &&
      String.fromCharCode(...bytes.subarray(start, start + 6)) === "Exif\0\0"
    ) {
      checkExifOrientation(bytes, start + 6, end);
    }
    if (marker === 0xda && dimensions) return dimensions;
    offset = end;
  }
  throw new Error("Unsupported or incomplete JPEG image.");
}

function inspectSourceImage(bytes, mimeType) {
  if (typeof mimeType !== "string" || !["image/jpeg", "image/png"].includes(mimeType)) {
    throw new Error("The host must return an image/jpeg or image/png content type.");
  }
  if (bytes.length < 45 || bytes.length > 2 * 1024 * 1024) {
    throw new Error("Use a JPEG or PNG file up to 2 MiB.");
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const bounds =
    mimeType === "image/png" ? pngDimensions(bytes, view) : jpegDimensions(bytes, view);
  if (bounds.width < 1 || bounds.height < 1 || bounds.width > 4096 || bounds.height > 4096) {
    throw new Error("Image width and height must each be at most 4,096 pixels.");
  }
  return { ...bounds, mimeType };
}

function detectionRequest(target, media, encoded) {
  return {
    contents: [
      {
        role: "user",
        parts: [
          {
            text:
              "Find every visible instance of this target description: " +
              target +
              "\nReturn each bounding box as [ymin, xmin, ymax, xmax] with integer coordinates from 0 through 1000, normalized to the entire image. Include a short label for each box. Return [] if no requested objects are visible.",
          },
          { inlineData: { mimeType: media.mimeType, data: encoded } },
        ],
      },
    ],
    generationConfig: {
      responseMimeType: "application/json",
      maxOutputTokens: 8192,
      responseJsonSchema: {
        type: "array",
        maxItems: 100,
        items: {
          type: "object",
          properties: {
            box_2d: {
              type: "array",
              minItems: 4,
              maxItems: 4,
              items: { type: "integer", minimum: 0, maximum: 1000 },
            },
            label: { type: "string" },
          },
          additionalProperties: false,
          required: ["box_2d", "label"],
        },
      },
    },
  };
}

const bytes = await helpers.getBinaryDataBuffer(0, "data");
if ($json.statusCode !== 200) throw new Error("Expected a complete image.");
const media = inspectSourceImage(bytes, $input.item.binary.data.mimeType);
return {
  json: {
    media,
    body: detectionRequest(
      $("Set the image and objects").item.json.target,
      media,
      Buffer.from(bytes).toString("base64"),
    ),
  },
};

function imageBoxes(response, width, height) {
  const selected = response?.candidates?.[0];
  if (selected?.finishReason !== "STOP" || !Array.isArray(selected.content?.parts)) {
    throw new Error("Gemini did not return a complete response.");
  }
  const text = selected.content.parts
    .filter((part) => part?.thought !== true)
    .map((part) => part?.text ?? "")
    .join("");
  if (text.length > 80000) throw new Error("Gemini returned an oversized box list.");
  let values;
  try {
    values = JSON.parse(text);
  } catch {
    throw new Error("Gemini returned invalid detection JSON.");
  }
  if (!Array.isArray(values) || values.length > 100)
    throw new Error("Expected an array of at most 100 boxes.");
  return values.map((item, index) => {
    const coords = item?.box_2d,
      label = typeof item?.label === "string" ? item.label.trim() : "";
    if (
      !Array.isArray(coords) ||
      coords.length !== 4 ||
      coords.some((n) => !Number.isInteger(n) || n < 0 || n > 1000) ||
      coords[2] <= coords[0] ||
      coords[3] <= coords[1] ||
      !label ||
      [...label].length > 160 ||
      /[\x00-\x1f\x7f]/.test(label)
    ) {
      throw new Error("Gemini returned an invalid box or label at item " + (index + 1) + ".");
    }
    const [ymin, xmin, ymax, xmax] = coords;
    return {
      label,
      xmin: (xmin * width) / 1000,
      ymin: (ymin * height) / 1000,
      xmax: (xmax * width) / 1000,
      ymax: (ymax * height) / 1000,
    };
  });
}

function imageOverlay(media, encoded, boxes) {
  const { width, height, mimeType } = media;
  const stroke = Math.max(2, Math.min(6, Math.round(Math.min(width, height) / 300)));
  const outlines = boxes
    .map(
      ({ xmin, ymin, xmax, ymax }) =>
        '<rect x="' +
        xmin +
        '" y="' +
        ymin +
        '" width="' +
        (xmax - xmin) +
        '" height="' +
        (ymax - ymin) +
        '"/>',
    )
    .join("");
  return (
    '<svg xmlns="http://www.w3.org/2000/svg" width="' +
    width +
    '" height="' +
    height +
    '" viewBox="0 0 ' +
    width +
    " " +
    height +
    '"><image width="' +
    width +
    '" height="' +
    height +
    '" href="data:' +
    mimeType +
    ";base64," +
    encoded +
    '"/><g fill="none" stroke="#ff00f2" stroke-width="' +
    stroke +
    '">' +
    outlines +
    "</g></svg>"
  );
}

const { media, body } = $("Read original dimensions and prepare Gemini input").item.json;
const boxes = imageBoxes($json, media.width, media.height);
const encoded = body.contents[0].parts[1].inlineData.data;
const svg = imageOverlay(media, encoded, boxes);
return {
  json: {
    svg: Buffer.from(svg, "utf8").toString("base64"),
    boxes,
    width: media.width,
    height: media.height,
  },
};
